solutionCode:
pub struct Ponto {
    pub x: i32,
    pub y: i32,
}

pub fn ponto_de(x: i32, y: i32) -> Ponto {
    Ponto { x: x, y: y }
}

pub fn abscissa(p: Ponto) -> i32 {
    p.x
}

pub fn mesma_abscissa(a: Ponto, b: Ponto) -> bool {
    a.x == b.x
}

testsCode:
use desafio::abscissa;
use desafio::mesma_abscissa;
use desafio::ponto_de;

#[test]
fn testa_a_abscissa_do_ponto_dois_por_tres() {
    assert_eq!(abscissa(ponto_de(2, 3)), 2);
}

#[test]
fn testa_a_abscissa_do_ponto_negativo_quatro_por_cinco() {
    assert_eq!(abscissa(ponto_de(-4, 5)), -4);
}

#[test]
fn testa_a_mesma_abscissa_dos_pontos_com_zero() {
    assert_eq!(mesma_abscissa(ponto_de(0, 9), ponto_de(0, 3)), true);
}

#[test]
fn testa_as_abscissas_diferentes() {
    assert_eq!(mesma_abscissa(ponto_de(2, 3), ponto_de(4, 3)), false);
}
